114	func sanitizeEvaluatedEnv(base, evaluated map[string]string, keepEnvrcMarker bool) map[string]string {
115		target := cloneEnv(base)
116		for key := range target {
117			if shouldIgnoreEvalKey(key) {
118				delete(target, key)
119			}
120		}
121		for key, val := range evaluated {
122			if key == "DIRENV_IN_ENVRC" {
123				if keepEnvrcMarker {
124					target[key] = val
125				}
126				continue
127			}
128			if shouldIgnoreEvalKey(key) {
129				continue
130			}
131			target[key] = val
132		}
133		for key := range target {
134			if key == "DIRENV_IN_ENVRC" {
135				if !keepEnvrcMarker {
136					delete(target, key)
137				}
138				continue
139			}
140			if shouldIgnoreEvalKey(key) {
141				delete(target, key)
142				continue
143			}
144			if _, ok := evaluated[key]; !ok {
145				delete(target, key)
146			}
147		}
148		for key, val := range base {
149			if shouldIgnoreEvalKey(key) {
150				target[key] = val
151			}
152		}
153		return target
154	}
