156	func shouldIgnoreEvalKey(key string) bool {
157		if key == "PWD" || key == "OLDPWD" || key == "SHLVL" || key == "_" {
158			return true
159		}
160		if key != "DIRENV_IN_ENVRC" && strings.HasPrefix(key, "DIRENV_") {
161			return true
162		}
163		if strings.HasPrefix(key, "BASH_") {
164			return true
165		}
166		switch key {
167		case "EPOCHREALTIME", "EPOCHSECONDS", "FUNCNAME", "GROUPS", "DIRSTACK", "HOSTTYPE", "MACHTYPE", "OSTYPE", "OPTERR", "OPTIND", "PIPESTATUS", "PPID", "PS4", "SHELLOPTS", "UID", "EUID":
168			return true
169		default:
170			return false
171		}
172	}
