174	func shellEscapeWord(word string) string {
175		var b strings.Builder
176		for _, r := range word {
177			if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || strings.ContainsRune("._/-", r) {
178				b.WriteRune(r)
179			} else {
180				b.WriteString("\\" + string(r))
181			}
182		}
183		return b.String()
184	}

